#include <iostream>
#include <set>

int main() {
    std::set<int> coll;  // Creates a balanced binary search tree for integers
    coll.insert(5);      // Inserts 5; runtime operation builds the tree node
    coll.insert(3);      // Inserts 3; tree rebalances if needed
    coll.insert(7);      // Inserts 7; maintains sorted order
    coll.insert(1);      // Inserts 1; no duplicates, so if already present, it's ignored

    std::set<int>::const_iterator pos;  // Iterator for read-only traversal
    for (pos = coll.begin(); pos != coll.end(); ++pos) {
        std::cout << *pos << ' ';  // Prints elements in sorted order
    }
    std::cout << std::endl;
    return 0;
}
